{
    if (tree == NULL)
        return (0);
    if (tree->left && tree->right)
        return (1 + double_btree_get_size(tree->left) +
        double_btree_get_size(tree->right));
    if (tree->left && !tree->right)
        return (1 + double_btree_get_size(tree->left));
    if (!tree->left && tree->right)
        return (1 + double_btree_get_size(tree->right));
    return (1);
}

