{
    int depth_left = 0;
    int depth_right = 0;

    if (tree == NULL)
        return (0);
    depth_left = double_btree_get_depth(tree->left);
    depth_right = double_btree_get_depth(tree->right);
    if (depth_left > depth_right)
        return (1 + depth_left);
    else
        return (1 + depth_right);
}

